    """
    ILO item 1.1.25: Diseases caused by thallium or its compounds.
    """
    osmium = "osmium"
    """
    ILO item 1.1.26: Diseases caused by osmium or its compounds.
    """
    selenium = "selenium"
    """
    ILO item 1.1.27: Diseases caused by selenium or its compounds.
    """
    copper = "copper"
    """
    ILO item 1.1.28: Diseases caused by copper or its compounds.
    """
    platinum = "platinum"
    """
    ILO item 1.1.29: Diseases caused by platinum or its compounds.
    """
    tin = "tin"
