class PublicationReference(ConfiguredBaseModel):
    """
    A reference to a publication with associated findings
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/monarch-initiative/dismech',
         'slot_usage': {'reference': {'identifier': True,
                                      'name': 'reference',
                                      'required': True},
                        'title': {'description': 'Title of the referenced publication. '
                                                 'Recommended so that linkml-data-qc '
                                                 'scores its absence, matching the '
                                                 '`recommended: true` already carried '
                                                 'by the EvidenceItem '
                                                 '`reference_title` twin. Set here via '
                                                 'slot_usage rather than on the shared '
                                                 '`title` slot, which is also used by '
                                                 'Dataset and TrackedIssue.',
                                  'name': 'title',
                                  'recommended': True}}})

    reference: str = Field(default=..., description="""The authoritative reference (publication) for this evidence item""", json_schema_extra = { "linkml_meta": {'domain_of': ['EvidenceItem', 'PublicationReference', 'MappingConsistency'],
         'examples': [{'value': 'PMID:35533128'}],
         'implements': ['linkml:authoritative_reference']} })
    title: Optional[str] = Field(default=None, description="""Title of the referenced publication. Recommended so that linkml-data-qc scores its absence, matching the `recommended: true` already carried by the EvidenceItem `reference_title` twin. Set here via slot_usage rather than on the shared `title` slot, which is also used by Dataset and TrackedIssue.""", json_schema_extra = { "linkml_meta": {'comments': ['The `linkml:title` annotation is INERT for '
                      "linkml-reference-validator detection — lrv's TitleURIs matches "
                      'only "dcterms:title" / "dc/terms/title". Where this slot IS '
                      "title-checked (on PublicationReference) that happens via lrv's "
                      'exact-name fallback FallbackSlotNames.TITLE = ("title",), not '
                      'via this annotation. Kept because it is a reasonable semantic '
                      'mapping, and noted here for the same reason the EvidenceItem '
                      '`reference_title` comment exists: an annotation that looks like '
                      'it enables a check, but does not, misleads readers. Retargeting '
                      'it to `dcterms:title` is deliberately left to the title '
                      'normalization work, since that would also newly expose '
                      'Dataset.title and TrackedIssue.title to detection.'],
         'domain_of': ['Dataset', 'PublicationReference', 'TrackedIssue'],
         'implements': ['linkml:title'],
         'recommended': True} })
    found_in: Optional[list[str]] = Field(default=None, description="""Deep-research output files where this reference was cited""", json_schema_extra = { "linkml_meta": {'domain_of': ['PublicationReference']} })
    tags: Optional[list[ReferenceTagEnum]] = Field(default=None, description="""Authoritative-source tags for a reference (e.g. GeneReviews). Populated programmatically by scripts/tag_references.py; use `just tag-references` to refresh.""", json_schema_extra = { "linkml_meta": {'domain_of': ['PublicationReference']} })
    findings: Optional[list[Finding]] = Field(default=None, description="""Key findings or claims extracted from this source (publication or dataset)""", json_schema_extra = { "linkml_meta": {'domain_of': ['Dataset',
                       'ExperimentalModel',
                       'ComputationalModel',
                       'PublicationReference']} })


