class ExposureClassifications(ConfiguredBaseModel):
    """
    Container for exposure- and agent-level classification assignments on an ``Environmental`` entry. Deliberately separate from ``DiseaseClassifications``: everything here classifies the agent or the exposure event (benzene is an IARC Group 1 carcinogen), not the disease.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/monarch-initiative/dismech'})

    hazard_agent_type: Optional[list[HazardAgentTypeAssignment]] = Field(default=None, description="""Occupational-hygiene classification of the agent by its nature (chemical, physical, biological, ergonomic, psychosocial, safety).""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExposureClassifications']} })
    exposure_route: Optional[list[ExposureRouteAssignment]] = Field(default=None, description="""Route(s) by which the agent reaches the organism. Multivalued: one agent commonly has more than one relevant route, and route can determine which disease results.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExposureClassifications']} })
    exposure_duration: Optional[list[ExposureDurationAssignment]] = Field(default=None, description="""Duration/pattern of the exposure, using the ATSDR day ranges. Describes the exposure, not the disease course.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExposureClassifications']} })
    iarc_carcinogen_group: Optional[IARCCarcinogenGroupAssignment] = Field(default=None, description="""IARC Monographs carcinogenicity group for the agent. A hazard identification about the AGENT, not a risk statement and not a claim that the agent caused this entry's disease.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExposureClassifications']} })
    ghs_health_hazard_class: Optional[list[GHSHealthHazardClassAssignment]] = Field(default=None, description="""UN GHS health hazard class(es) for the agent. Record the numbered category (e.g. \"Carc. 1A\") in ``notes``; categories are class-specific and are not enumerated.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExposureClassifications']} })
    exposome_domain: Optional[list[ExposomeDomainAssignment]] = Field(default=None, description="""Domain of the exposome (Wild 2012) this exposure sits in. A framing device for exposome-scale epidemiology, not a regulatory instrument; domains overlap by design.""", json_schema_extra = { "linkml_meta": {'domain_of': ['ExposureClassifications']} })


class DiseaseClassifications(ConfiguredBaseModel):
    """
    Container for all classification assignments for a disease
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/monarch-initiative/dismech'})

    icdo_morphology: Optional[ICDOMorphologyAssignment] = Field(default=None, title="ICD-O Morphology", description="""ICD-O morphology classification (for neoplastic diseases)""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    harrisons_chapter: Optional[list[HarrisonsChapterAssignment]] = Field(default=None, title="Harrison's Part", description="""Harrison's internal medicine chapter classification""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    lysosomal_storage_category: Optional[LysosomalStorageAssignment] = Field(default=None, title="Lysosomal Storage", description="""Lysosomal storage disease biochemical classification""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    mechanistic_category: Optional[list[MechanisticNosologyAssignment]] = Field(default=None, title="Mechanistic Nosology", description="""Mechanistic/pathway-based disease classification""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    iuis_category: Optional[IUISAssignment] = Field(default=None, title="IUIS Category", description="""IUIS primary immunodeficiency classification""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    channelopathy_category: Optional[ChannelopathyAssignment] = Field(default=None, title="Channelopathy", description="""Channelopathy organ system classification""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    icimd_category: Optional[list[ICIMDAssignment]] = Field(default=None, title="ICIMD (Inherited Metabolic Disorders)", description="""International Classification of Inherited Metabolic Disorders (ICIMD) category/group classification (for inherited metabolic disorders)""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    isds_skeletal_category: Optional[list[ISDSNosologyAssignment]] = Field(default=None, title="ISDS Skeletal Nosology", description="""ISDS Nosology and Classification of Genetic Skeletal Disorders group assignment (for genetic skeletal disorders). Assign only to entries the Nosology itself lists (or an unambiguous subtype/synonym of one); a single listed disorder carries exactly one group.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    nih_research_priority: Optional[list[NIHResearchPriorityAssignment]] = Field(default=None, title="NIH Highlighted Topic", description="""NIH \"Highlighted Topics\" funding-priority area(s) this disease is relevant to. A secondary, soft, grant-strategy classification (NOT a nosology); an entry may carry several or none.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications']} })
    ilo_agent_category: Optional[list[ILOCausativeAgentAssignment]] = Field(default=None, title="ILO (revised 2010) — by causative agent", description="""Item(s) on the **causative-agent axis** of the ILO List of Occupational Diseases (revised 2010, annexed to Recommendation No. 194) — sections 1 (chemical, physical, biological agents) and 3 (occupational cancer). The item names the agent, not the disease. Orthogonal to ``ilo_disease_category``; a disease commonly carries both. Assign only when an occupational form of the disease is recognised.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications'],
         'slot_group': 'occupational_classification'} })
    ilo_disease_category: Optional[list[ILODiseaseCategoryAssignment]] = Field(default=None, title="ILO (revised 2010) — by disease category", description="""Item(s) on the **disease-category axis** of the ILO List of Occupational Diseases (revised 2010) — section 2 (by target organ system) and section 4 (other diseases). The item names a clinical entity, not the agent. Orthogonal to ``ilo_agent_category``. Multivalued because more than one item from this axis can apply: silicosis takes both 2.1.1 and 2.1.2.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications'],
         'slot_group': 'occupational_classification'} })
    eu_occupational_category: Optional[list[EUOccupationalScheduleAssignment]] = Field(default=None, title="European schedule", description="""Item(s) of the European schedule of occupational diseases (Commission Recommendation 2003/670/EC as amended by 2022/2337 and 2025/2609) that this disease appears under. Annex II values record a SUSPECTED, not established, occupational aetiology and must say so in ``notes``. Unlike the ILO list the European schedule is not biaxial — it indexes by agent or route throughout — so it takes a single slot.""", json_schema_extra = { "linkml_meta": {'domain_of': ['DiseaseClassifications'],
         'slot_group': 'occupational_classification'} })


