                       'ReferenceRangeBand',
                       'SurrogateEndpointCollection',
                       'ExternalAssertion',
                       'EpidemiologyInfo',
                       'Pathophysiology',
                       'Phenotype',
                       'Biochemical',
                       'HistopathologyFinding',
                       'ImagingFinding',
                       'Genetic',
                       'Environmental',
                       'Disease',
                       'Stage',
